html,body{margin:0;height:100%;background:#0f172a;font-family:'Open Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#e2e8f0;}
*{box-sizing:border-box;}
.wrap{height:calc(var(--appsmith-ui-height)*1px);overflow-y:auto;overflow-x:hidden;padding:18px 26px 48px;}
.top{display:flex;align-items:flex-start;gap:40px;margin-bottom:6px;}
.fld label{display:block;font-size:14px;color:#60a5fa;font-weight:600;margin-bottom:8px;}
.fld select,.dateinput{background:#1e293b;color:#e2e8f0;border:1px solid #334155;border-radius:6px;padding:9px 12px;font-size:14px;min-width:260px;outline:none;cursor:pointer;height:40px;}
.fld select:focus{border-color:#3b82f6;}
.dateinput{display:flex;align-items:center;gap:8px;}
.dateinput .ph{color:#94a3b8;} .dateinput.has .ph{color:#e2e8f0;}
.dateinput .clr{margin-left:auto;color:#94a3b8;font-size:15px;padding:0 2px;}
.dateinput .clr:hover{color:#e2e8f0;}
.pop{position:absolute;top:74px;left:0;z-index:50;background:#1e293b;border:1px solid #334155;border-radius:10px;box-shadow:0 12px 30px rgba(0,0,0,.5);padding:14px;width:340px;}
.pop .nav{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;}
.pop .nav b{font-size:15px;color:#f1f5f9;}
.pop .nav span{cursor:pointer;color:#cbd5e1;font-size:20px;padding:2px 10px;border-radius:6px;line-height:1;}
.pop .nav span:hover{background:#334155;}
.pop .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;}
.pop .grid b{text-align:center;padding:13px 0;border-radius:8px;font-size:14px;font-weight:600;color:#cbd5e1;cursor:pointer;}
.pop .grid b:hover{background:#334155;}
.pop .grid b.on{background:#2563eb;color:#fff;}
.grp{margin-top:26px;}
.ghead{display:flex;justify-content:space-between;align-items:baseline;padding:6px 2px 10px;border-bottom:1px solid #334155;margin-bottom:2px;}
.gmonth{font-size:17px;font-weight:800;color:#f8fafc;}
.gtot{font-size:14px;color:#cbd5e1;}
table{width:100%;border-collapse:collapse;font-size:14px;}
thead th{color:#94a3b8;font-weight:700;text-align:right;padding:10px 14px;white-space:nowrap;border-bottom:1px solid #1e293b;font-size:13px;}
thead th:first-child,thead th:nth-child(2),thead th:last-child{text-align:left;}
tbody td{padding:11px 14px;text-align:right;white-space:nowrap;color:#e2e8f0;}
tbody td:first-child,tbody td:nth-child(2),tbody td:last-child{text-align:left;}
tbody tr:nth-child(odd){background:#1e293b;}
.link{color:#60a5fa;cursor:pointer;font-weight:600;}
.totrow td{font-weight:700;color:#f1f5f9;border-top:1px solid #334155;background:transparent !important;}
.empty{padding:40px;text-align:center;color:#64748b;font-style:italic;}
::-webkit-scrollbar{width:10px;height:10px;background:#0f172a;} ::-webkit-scrollbar-thumb{background:#1e293b;border-radius:4px;border:2px solid #0f172a;}

